"""The EO auto-retry JSON the UI consumes, generated by the real code (synthetic data only) and compared with
the fixtures the jest tests render (``packages/fpl-ui/__tests__/fixtures/eo/``). If the backend shape changes,
this test fails until the fixtures are regenerated (``UPDATE_EO_FIXTURES=1 pytest tests/test_eo_wire_fixtures.py``),
so the UI tests cannot keep rendering a shape the backend no longer returns."""
from __future__ import annotations

import json
import os
import pathlib

import pytest

import fpl_server
from fpl_grounded_assistant import eo_poll, harness, league_eo_tool
from fpl_grounded_assistant.conversation_fixtures import STANDARD_BOOTSTRAP
from fpl_grounded_assistant.harness_adapter import to_ask_response
from fpl_grounded_assistant.orchestrator import OrchestratorResult

from test_eo_poll import CARD_OK  # noqa: E402  (a real near-rank ok result, synthetic players)
from test_league_eo_tool import BOOT as LEAGUE_BOOT, DATA as LEAGUE_DATA  # noqa: E402

FIXTURES = pathlib.Path(__file__).resolve().parents[2] / "fpl-ui" / "__tests__" / "fixtures" / "eo"
MODEL_TEXT = "Se esta calculando; pregunta de nuevo en unos segundos."


def _computing_turn(monkeypatch, tool_name, raw):
    """The /ask JSON of a turn whose EO tool answered ``computing``: outcome unsupported, model text, ``pending``."""
    trace = ({"round": 1, "tool_call_id": "1", "name": tool_name, "args": {}, "output": raw, "success": False},)
    orch = OrchestratorResult(question="q", tool_chosen=tool_name, tool_args={}, tool_output=raw,
                              answer_text=MODEL_TEXT, llm_used=True, model="controlled", outcome="tool_result_error",
                              synthesis_turn=True, tool_call_count=1, tool_calls_trace=trace)
    monkeypatch.setenv("FPL_ORCH_ENABLED", "1")
    monkeypatch.setattr("fpl_grounded_assistant.harness._build_eval_client", lambda *a, **k: None)
    monkeypatch.setattr("fpl_grounded_assistant.orchestrator.ask_orchestrated", lambda *a, **k: orch)
    d = harness.ask_v2("EO", dict(STANDARD_BOOTSTRAP), orch_client=object(), team_id=555, locale="es")
    return to_ask_response(d, fpl_server.AskRequest(question="EO", team_id=555), dict(STANDARD_BOOTSTRAP), "es").model_dump(mode="json")


def _ready(monkeypatch, tool_name, raw):
    monkeypatch.setattr("fpl_grounded_assistant.near_rank_eo_tool.get_near_rank_eo", lambda boot, **k: raw)
    monkeypatch.setattr("fpl_grounded_assistant.league_eo_tool.get_league_eo", lambda boot, **k: raw)
    return eo_poll.poll(tool_name, 555, 42 if tool_name == "get_league_eo" else None, dict(STANDARD_BOOTSTRAP), "es")


def _tap(monkeypatch, question, tool_results, picker=None):
    """The /ask JSON of an EO chip tap answered without a model (tool results canned)."""
    monkeypatch.setattr("fpl_grounded_assistant.tool_dispatch.run_tool", lambda name, args, boot: tool_results[name])
    monkeypatch.setattr("fpl_grounded_assistant.league_eo_tool.league_picker", lambda boot, now=None: picker)

    class Cached:  # the user's league list as the service has it cached (a tap checks a league name against it)
        def cached_leagues(self, entry_id):
            return [{"id": 42, "name": "Friends", "size": 12}, {"id": 77, "name": "Work Mates", "size": 48}]

    monkeypatch.setattr(league_eo_tool, "_SERVICE", Cached())  # restored by monkeypatch after the test
    d = harness.ask_v2(question, dict(STANDARD_BOOTSTRAP), team_id=555, locale="es")
    assert d["routing_trace"]["decision_kind"] == "eo_tap"
    return to_ask_response(d, fpl_server.AskRequest(question=question, team_id=555), dict(STANDARD_BOOTSTRAP), "es").model_dump(mode="json")


def _near_with_squad():
    """A real ok near-rank result where the user's squad was compared (so the one line has content)."""
    from fpl_grounded_assistant import near_rank_eo_tool as tool
    from test_eo_poll import _stats

    boot = {"teams": [{"id": t, "short_name": f"T{t}"} for t in range(1, 5)],
            "elements": [{"id": i, "web_name": f"P{i}", "second_name": f"S{i}", "team": (i % 4) + 1} for i in range(1, 21)]}
    data = {"gw": 12, "user_rank": 1000, "n_sampled": 100, "players": {"1": _stats(90.0, 95.0), "2": _stats(10.0, 12.0, 0.0)}}
    return tool.shape_result(data, boot, [], {"status": "ok", "players": [{"id": 2}]})


def _fixtures(monkeypatch):
    others = [{"league_id": 77, "name": "Work Mates", "size": 48}]
    squad = {"status": "ok", "players": [{"id": 2}]}
    league_ok = league_eo_tool.shape_result(LEAGUE_DATA, LEAGUE_BOOT, [], squad, others)
    near_ok = {**_near_with_squad(), "main_league": {"id": 42, "name": "Friends"}}
    picker = {"status": "ok", "stage": "needs_league", "message": "x", "leagues": others}
    return {
        "tap-ready-league.json": _tap(monkeypatch, "EO en Friends", {"get_league_eo": league_ok}),
        "tap-computing-league.json": _tap(monkeypatch, "EO en Friends", {
            "get_league_eo": {"status": "computing", "tier": "league", "eta_s": 30, "league_id": 42}}),
        "tap-change-league.json": _tap(monkeypatch, "Cambiar de liga", {}, picker),
        "computing-league.json": _computing_turn(
            monkeypatch, "get_league_eo", {"status": "computing", "tier": "league", "eta_s": 30, "league_id": 42}),
        "computing-near.json": _computing_turn(
            monkeypatch, "get_near_rank_eo", {"status": "computing", "tier": "near", "eta_s": 30}),
        "ready-league.json": _ready(monkeypatch, "get_league_eo", league_ok),
        "ready-near.json": _ready(monkeypatch, "get_near_rank_eo", near_ok),
        "needs-league.json": _ready(monkeypatch, "get_league_eo", {
            "status": "ok", "stage": "needs_league", "message": "x",
            "leagues": [{"league_id": 42, "name": "Friends", "size": 12}, {"league_id": 77, "name": "Work Mates", "size": 48}]}),
    }


def test_the_ui_fixtures_are_what_the_backend_really_returns(monkeypatch):
    built = _fixtures(monkeypatch)
    assert built["computing-league.json"]["outcome"] == "unsupported_intent" and built["computing-league.json"]["pending"]
    assert built["needs-league.json"]["status"] == "needs_league"
    assert built["ready-league.json"]["status"] == "ready" and built["ready-near.json"]["status"] == "ready"
    if os.environ.get("UPDATE_EO_FIXTURES"):
        FIXTURES.mkdir(parents=True, exist_ok=True)
        for name, payload in built.items():
            (FIXTURES / name).write_text(json.dumps(payload, indent=2, sort_keys=True, ensure_ascii=False) + "\n", encoding="utf-8")
    for name, payload in built.items():
        path = FIXTURES / name
        assert path.exists(), f"missing {name}: run UPDATE_EO_FIXTURES=1 pytest tests/test_eo_wire_fixtures.py"
        assert json.loads(path.read_text(encoding="utf-8")) == json.loads(json.dumps(payload, sort_keys=True)), \
            f"{name} drifted from the backend: regenerate with UPDATE_EO_FIXTURES=1"
